import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 분석 유형 다섯 가지는 모두 같은 집계를 쓴다 (유형별 별도 산식 없음).
const ANALYSIS_TYPES = ['통계', '통상급여', '급여변동', '증감', '인건비손익'];
// 가정: 급여 열람 로그의 열람 대상 정보 유형, 로그인 구분, 접속 IP 기본값
const TARGET_INFO_TYPE = '급여정보';
const LOG_LOGIN_TYPE = '웹';
const DEFAULT_IP = '0.0.0.0';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const INT_PATTERN = /^\d+$/;

function textOf(value: unknown): string {
  if (value === undefined || value === null) {
    return '';
  }
  return String(value).trim();
}

function optionalId(value: unknown, label: string): string | null {
  const text = textOf(value);
  if (text === '') {
    return null;
  }
  if (!INT_PATTERN.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr02113Controller {
  @Get('/payroll-analyses')
  async listPayrollAnalyses(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const query = checks.queryOf(req.query);
    const analysisType = textOf(query['analysisType']);
    if (!ANALYSIS_TYPES.includes(analysisType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '분석 유형을 선택해 주세요.');
    }
    const startDate = textOf(query['startDate']);
    const endDate = textOf(query['endDate']);
    if (!DATE_PATTERN.test(startDate) || !DATE_PATTERN.test(endDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일과 종료일을 입력해 주세요.');
    }
    const departmentId = optionalId(query['departmentId'], '주부서');
    const employeeId = optionalId(query['employeeId'], '임직원 ID');
    const pageText = textOf(query['page']) || '0';
    const sizeText = textOf(query['size']) || String(DEFAULT_SIZE);
    if (!INT_PATTERN.test(pageText) || !INT_PATTERN.test(sizeText) || Number(sizeText) < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 크기가 올바르지 않습니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Number(sizeText), MAX_SIZE);
    const ip = (req.ip || DEFAULT_IP).slice(0, 45);

    return transaction(async (db) => {
      const periodRows = await db.query(
        'SELECT (CAST(:startDate AS date) > CAST(:endDate AS date)) AS "invalid"',
        { startDate, endDate },
      );
      if (periodRows[0]['invalid']) {
        throw new ApiError(422, 'INVALID_PERIOD', '조회 기간이 올바르지 않습니다.');
      }

      // 급여 정보 열람 로그
      await db.execute(
        'INSERT INTO access_log (employee_id, event_type, accessed_at, login_ip, login_type, target_info_type, created_at, updated_at) ' +
          "VALUES (CAST(:userId AS bigint), '개인정보열람', now(), :ip, :loginType, :targetInfoType, now(), now())",
        { userId: user.id, ip, loginType: LOG_LOGIN_TYPE, targetInfoType: TARGET_INFO_TYPE },
      );

      const params = { startDate, endDate, departmentId, employeeId, limit: size, offset: page * size };
      const filter =
        ' WHERE (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))' +
        ' AND (CAST(:employeeId AS bigint) IS NULL OR e.employee_id = CAST(:employeeId AS bigint))';

      const countRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM employee e' + filter,
        { startDate, endDate, departmentId, employeeId },
      );

      // 가정: 증감액 = 조회 기간 지급 합계 - 직전 같은 길이 기간의 지급 합계
      const periodCur = 'd.pay_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date)';
      const periodPrev =
        'd.pay_date BETWEEN CAST(:startDate AS date) - (CAST(:endDate AS date) - CAST(:startDate AS date) + 1)' +
        ' AND CAST(:startDate AS date) - 1';
      const sql =
        'SELECT r.employee_id AS "employeeId", r.name AS "employeeName", r.assigned AS "assignedSalary",' +
        ' r.total_cur AS "totalPaymentAmount", r.amount_cur AS "amount", (r.total_cur - r.total_prev) AS "changeAmount" FROM (' +
        ' SELECT e.employee_id, e.name,' +
        ' (SELECT s.assigned_salary FROM employee_salary s WHERE s.employee_id = e.employee_id' +
        ' AND s.applied_from <= CAST(:endDate AS date) ORDER BY s.applied_from DESC LIMIT 1) AS assigned,' +
        ' COALESCE((SELECT SUM(p.total_payment_amount) FROM payroll p JOIN payday d ON d.payday_id = p.payday_id' +
        ' WHERE p.employee_id = e.employee_id AND ' + periodCur + '), 0) AS total_cur,' +
        ' COALESCE((SELECT SUM(p.total_payment_amount) FROM payroll p JOIN payday d ON d.payday_id = p.payday_id' +
        ' WHERE p.employee_id = e.employee_id AND ' + periodPrev + '), 0) AS total_prev,' +
        ' COALESCE((SELECT SUM(a.amount) FROM payroll_item_amount a JOIN payroll p ON p.payroll_id = a.payroll_id' +
        ' JOIN payday d ON d.payday_id = p.payday_id' +
        " WHERE p.employee_id = e.employee_id AND a.pay_item_id IN (SELECT pay_item_id FROM pay_item WHERE item_category = '지급')" +
        ' AND ' + periodCur + '), 0) AS amount_cur' +
        ' FROM employee e' + filter + ') r ORDER BY r.employee_id LIMIT :limit OFFSET :offset';
      const items = await db.query(sql, params);

      return { items, page, size, total: Number(countRows[0]['total']) };
    });
  }
}

