import { useState } from 'react';
import {
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Num,
  Pager,
  Pairs,
  Select,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Column, PageProps, Row } from '../kit';
import type { Page } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['통계', '급여통계 현황'],
  ['통상급여', '통상급여 현황'],
  ['급여변동', '사원별 급여변동 현황'],
  ['증감', '급여 증감 현황'],
  ['인건비손익', '인건비 손익 현황'],
];

const SIZE = 20;

export default function FnSfr02113Page({ role, notify }: PageProps) {
  const [analysisType, setAnalysisType] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState(0);
  const [formError, setFormError] = useState('');
  const [detail, setDetail] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page | null>(async () => {
    if (applied === null) {
      return null;
    }
    return call<Page>('GET', '/payroll-analyses', role, undefined, { ...applied, page, size: SIZE });
  }, [applied, page]);

  const search = () => {
    if (!analysisType || !startDate || !endDate) {
      setFormError('분석 유형, 조회 시작일, 조회 종료일을 입력해 주세요.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ analysisType, startDate, endDate, departmentId, employeeId });
    notify('급여 분석 현황을 조회했습니다.');
  };

  const reset = () => {
    setAnalysisType('');
    setStartDate('');
    setEndDate('');
    setDepartmentId('');
    setEmployeeId('');
    setApplied(null);
    setPage(0);
    setFormError('');
  };

  const items = data ? data.items : [];
  const sum = (key: string) => items.reduce((acc, row) => acc + Number(row[key] ?? 0), 0);

  const columns: Column[] = [
    { key: 'employeeName', label: '성명' },
    { key: 'assignedSalary', label: '책정임금', render: (row) => <Num value={row.assignedSalary} /> },
    { key: 'totalPaymentAmount', label: '지급 합계', render: (row) => <Num value={row.totalPaymentAmount} /> },
    { key: 'amount', label: '금액', render: (row) => <Num value={row.amount} /> },
    { key: 'changeAmount', label: '기간 대비 증감액', render: (row) => <Num value={row.changeAmount} /> },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 건수·합계</h2>
        <Tiles
          items={[
            ['조회 인원', <Num value={data ? data.total : 0} />],
            ['지급 합계(현재 쪽)', <Num value={sum('totalPaymentAmount')} />],
            ['금액(현재 쪽)', <Num value={sum('amount')} />],
            ['증감액(현재 쪽)', <Num value={sum('changeAmount')} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>급여 분석 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="분석 유형" required>
            <Select value={analysisType} onChange={setAnalysisType} options={TYPE_OPTIONS} />
          </Field>
          <Field label="조회 시작일" required>
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="주부서">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
          </Field>
          <Field label="임직원 ID">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={data ? data.total : 0} />
        <DataTable
          columns={columns}
          rows={items}
          onRowClick={(row) => setDetail(row)}
          empty={loading ? '불러오는 중입니다.' : '분석 유형과 기간을 선택하고 조회해 주세요.'}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {detail ? (
        <Drawer title="급여 분석 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['성명', String(detail.employeeName ?? '')],
              ['책정임금', <Num value={detail.assignedSalary} />],
              ['지급 합계', <Num value={detail.totalPaymentAmount} />],
              ['금액', <Num value={detail.amount} />],
              ['기간 대비 증감액', <Num value={detail.changeAmount} />],
              ['조회 시작일', <DateText value={applied ? applied.startDate : ''} />],
              ['조회 종료일', <DateText value={applied ? applied.endDate : ''} />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
